          },
          "c": {
            "type": "array",
            "items": {
              "type": "number"
            },
            "minItems": 3,
            "maxItems": 3
          }
        }
      }
    },
    "required": [
      "name",
      "CAS",
      "Tc",
      "Tc_units",
      "pc",
      "pc_units",
      "acentric",
      "molemass",
      "molemass_units"
    ]
  },
  "type": "array"
}

